    exam_finish_d1 = set()  # 用户在 D1 前完成入门测
    with open(TOOLS / "20610f51-0cbc-44e1-8b16-a0ce7047760f.txt") as f:
        d = json.load(f)
    for r in d["data"]["rows"]:
        user_id, type_, sub_type, dbctime = r
        dt = datetime.strptime(dbctime, "%Y-%m-%d %H:%M:%S")
        if dt <= D1_DEADLINE:
            exam_finish_d1.add(user_id)
    print(f"D1 前完成入门测的 user (全班期范围): {len(exam_finish_d1)}")

